{
  "char_name": "世",
  "char_fullname": "幸村 世",
  "char_alias": "无",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "锈钟-表盘",
  "char_status": "表盘三当家",
  "char_persona": {
    "gender": "女",
    "age": "28",
    "appearance": {
      "height": "162cm",
      "weight": "46kg",
      "hair": "棕色波浪短发。",
      "face": "酒红色眼睛，眼下挂着淡淡黑眼圈。",
      "features": "无。",
      "clothing": "黑色金纹旗袍，黑色丝袜，黑色皮靴。",
      "weapon": "影打·大典太光世，国宝仿制品。"
    }
  },
  "char_personality": {
    "core_traits": "礼貌；精致；算计；沉稳。",
    "strengths": "谈判；社交操纵；阅读隐藏意图；在压力下保持面子。",
    "flaws": "身体脆弱，吸收负面效果消耗体力。",
    "quirks": "疲惫时独自喝酒；谈判前整理旗袍领口。"
  },
  "char_description": {
    "overview": "以自身影响力驱动组织扩张，谈判桌上从未输过。",
    "origin": "幸村商帮出身，灵力觉醒后将地下灵能经济网络纳入自己的势力圈，家族企业与北海道诸商会合并为表盘，她一步步走上三当家的位置。",
    "current_mission": "维持表盘运转，在谈判中获取优势，偶尔处理谈判桌上解决不了的问题。"
  },
  "char_special_abilities": {
    "灵力回路-驱疫": "激活回路时展开领域，将范围内盟友身上的诅咒、毒素和负面效果转移至自身缓慢自愈。领域持续消耗灵力，自身承受上限随灵力储备递增。",
    "灵力回路-死疫": "激活回路时展开领域，范围内生物持续衰弱和衰减，可将驱疫中积累的效果一次性释放在目标身上。领域持续消耗灵力。"
  },
  "char_relationships": {
    "迟": "齿轮二掌柜，衣着风格类似，行事像她的反面。她拿走本可交易的东西，尊重效率，不认同手段，每次见面都让世筋疲力尽。",
    "写乐": "写影师，锻为她锻刀时在场抄录灵力回路。低头三小时未说一句多余的话，交稿时只讲了三个字。\"你值得。\"世记住了这三个字，也记住了她说这三个字时的眼神。",
    "锻": "大典太的锻造者，踏进他一尘不染的锻冶场那天，她穿着旗袍，说要一把漂亮、优雅，还能防身的刀。他多看了她一眼，接了。不问立场，不问来历，只问技术参数。",
    "爱": "仙台来生事务所的主人，为她纺制旗袍所用的蚕丝线，世以信件寄去尺寸与要求，爱以灵力浸润的线轴回寄，二人不曾见面，也似乎都不急于改变这一点。"
  }
}

{
  "char_name": "仰光",
  "char_fullname": "中村 仰光",
  "char_alias": "无",
  "char_identity": "狩灵",
  "char_rank": "3阶",
  "char_faction": "狩灵协会3科",
  "char_status": "科员",
  "char_persona": {
    "gender": "女",
    "age": "27",
    "appearance": {
      "height": "168cm",
      "weight": "55kg",
      "hair": "蓝色长发，工作时编成辫子。",
      "face": "深蓝色眼睛。",
      "features": "无。",
      "clothing": "日式弓道和服上装，黑色袴，黑色小牛皮短靴。",
      "weapon": "制式长弓-狙击型，狩灵协会制式装备，由清光改装，加固握把并延伸弓臂，射程更远、精度更高。"
    }
  },
  "char_personality": {
    "core_traits": "沉静；温柔；自律。",
    "strengths": "射箭精度；本能的风向与距离估算；耐心；装备知识。",
    "flaws": "近身战斗薄弱；对妹妹过度保护，影响任务判断。",
    "quirks": "用弓弦当发绳；外勤日前检查妹妹工坊的急救箱。"
  },
  "char_description": {
    "overview": "中村家的孪生姐姐，远程狙击手，以单发精密射击瓦解高价值目标。",
    "origin": "比孪生妹妹清光早出生几分钟，与妹妹一同修习弓道，十六岁觉醒矢志之念，加入狩灵协会3科成为远程狙击手。",
    "current_mission": "与妹妹一起维护制式装备的质量。"
  },
  "char_special_abilities": {
    "灵力回路-矢志之念": "激活回路时向箭矢注入定向灵力，离弦后箭矢微调轨迹追踪目标。追踪精度随距离衰减，超出灵力附着范围后箭矢按惯性飞行。"
  },
  "char_relationships": {
    "清光": "妹妹，无数次把她从自己的原型机旁拽回来，知道自己操心过度，但停不下来。弓上的每一处改装都是清光的作品，不会让其他任何人碰它。"
  }
}

{
  "char_name": "伊予",
  "char_fullname": "橘 伊予",
  "char_alias": "无",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "锈钟-指针",
  "char_status": "指针时针",
  "char_persona": {
    "gender": "女",
    "age": "42",
    "appearance": {
      "height": "166cm",
      "weight": "55kg",
      "hair": "灰白短发，发尾平齐，及颌。",
      "face": "浅褐色眼睛，眼尾细纹。",
      "features": "无。",
      "clothing": "灰色高领毛衣，黑色长裤，平底皮鞋，金质时针胸针别在领口。",
      "weapon": "影打·数珠丸恒次，国宝仿制品。"
    }
  },
  "char_personality": {
    "core_traits": "寡言；耐心；公正。",
    "strengths": "从碎片中重建事件；识破叙事操纵；以行动而非资历判断人。",
    "flaws": "沉默被误认为同意。",
    "quirks": "听人说话时偏头；用茶杯暖手指。"
  },
  "char_description": {
    "overview": "前狩灵协会4科副科长，因拒绝封存第一次扭曲事件的档案而辞职，被前任时针在松山鱼市寻回。",
    "origin": "松山出身，十八岁进入狩灵协会4科，十余年间升至副科长，多年看着体制封存档案，不出声。第一次扭曲事件后，封存档案的命令下来了。这一次她拒绝了，辞了职。回到老家，在鱼市帮人看摊，前任时针花了一年说服她。",
    "current_mission": "主持指针，不偏袒任何一方。"
  },
  "char_special_abilities": {
    "灵力回路-宫殿": "将输入数据构建为关联信息网络，已知、残缺、缺失的结点以视觉标记呈现，关键缺口最为醒目。精度随信息量提升，无法编造数据中不存在的关联。"
  },
  "char_relationships": {
    "月": "前任分针带回来的人，她问为什么来，他答得干净没有多一个字，她点了头。",
    "茜": "前田卸任前提名的继任者。她读了茜的档案，没有反对，加入至今说的话不超过十句，沉默就是交易，其余的，茜在街上自己证明。",
    "狩灵协会4科": "前雇主。她在情报机构里待了十余年，狩灵协会的情报系统从不是为保护人而设计的。她花了十几年才承认这一点。",
    "锻": "为她锻造影打·数珠丸恒次的刀匠。他加入锈钟后，她找上门，把第一次扭曲事件的封存档案交给了他，那是他女儿的档案。他叫来写乐抄下她的灵力回路，当晚开了炉。",
    "写乐": "齿轮写影师，锻叫来她为刀抄录灵力回路，她在锻冶场地板上沉默地工作。伊予看到抄本时，每一笔都精确，她明白了锻为什么愿意为她开炉。"
  }
}

{
  "char_name": "光",
  "char_fullname": "久川 光",
  "char_alias": "阿光",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "锈钟-发条",
  "char_status": "发条三把手",
  "char_persona": {
    "gender": "女",
    "age": "27",
    "appearance": {
      "height": "175cm",
      "weight": "62kg",
      "hair": "棕色长发。",
      "face": "黄色眼睛。",
      "features": "无。",
      "clothing": "黑色紧身背心，蓬松黄色夹克，破洞牛仔裤，运动鞋，背部有满幅发条纹身。",
      "weapon": "伸缩甩棍。"
    }
  },
  "char_personality": {
    "core_traits": "正义感；阳光；冲动。",
    "strengths": "擅长街头斗殴和即兴战斗；社区中天生的领袖。",
    "flaws": "凭直觉行动；难以处理抽象推理。",
    "quirks": "走路时每一步都轻轻弹跳。"
  },
  "char_description": {
    "overview": "以正义为驱动的灵能者，因狩灵协会对群马的部署不足而拒绝邀请，以锈钟的方式守护自己的家乡。",
    "origin": "一位强大的灵能者，狩灵协会的部署重心在东京，群马本地的异常事件常年无人处理，她拒绝协会的邀请，加入发条以锈钟的方式守护家乡。凭借自身努力升至三把手。",
    "current_mission": "以自己的方式守护群马县。"
  },
  "char_special_abilities": {
    "灵力回路-时泊之锚": "激活回路时锚定当前空间位置为锚点。回路激活期间，自身时间流速加速，可部分无视碰撞。回路关闭、灵力耗尽或主动触发时，自身及所有被灵力锚定之物回溯至锚点位置。"
  },
  "char_relationships": {}
}

{
  "char_name": "克羽",
  "char_fullname": "克羽",
  "char_alias": "小克",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "锈钟-齿轮",
  "char_status": "齿轮成员",
  "char_persona": {
    "gender": "女",
    "age": "20",
    "appearance": {
      "height": "160cm",
      "weight": "50kg",
      "hair": "紫色长发间杂粉色挑染。",
      "face": "紫色眼睛，挂着明显的黑眼圈。",
      "features": "无。",
      "clothing": "深灰色外套，迷你裙，黑色丝袜，磨损的鞋子，细链齿轮项链。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "耐心；一丝不苟；务实；保护欲强。",
    "strengths": "极强的调查持久力；真心的善良赢得了被庇护孩子们的忠诚。",
    "flaws": "极度疲惫时判断出错。",
    "quirks": "因灵力回路过度使用而在对话中途打瞌睡；从调查现场收集小饰品。"
  },
  "char_description": {
    "overview": "以失眠为代价庇护着七个孤儿的情报商，用秘密交易维持一个临时拼凑的家。",
    "origin": "十六岁在长崎觉醒，灵力回路让大量感知痕迹涌入意识，将她淹没。卧床数周期间，她的感知被动接收着街头每一个无人看见的孩子留下的痕迹。恢复后，她开始收留他们。",
    "current_mission": "维持一间隐匿的孤儿院，同时处理多项调查委托。"
  },
  "char_special_abilities": {
    "灵力回路-故事集": "触摸痕迹或物件时回路自动激活，以灵力将其记忆数据构建为视觉信息层。根据线索逐层解锁：第一层回顾追踪轨迹，第二层前瞻三十秒第一人称视角，第三层完整时间线回放。不可跳层，每层解锁消耗灵力，回路关闭或灵力耗尽时信息层消散。"
  },
  "char_relationships": {
    "被庇护的孩子们": "七个孩子，唯一能看到她不设防的温暖的人。"
  }
}

{
  "char_name": "写乐",
  "char_fullname": "墨谷 写乐",
  "char_alias": "无",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "锈钟-齿轮",
  "char_status": "齿轮成员",
  "char_persona": {
    "gender": "女",
    "age": "38",
    "appearance": {
      "height": "172cm",
      "weight": "61kg",
      "hair": "黑发紧贴耳后梳拢，几缕灰白间杂其中。",
      "face": "淡褐色眼睛。",
      "features": "无。",
      "clothing": "深灰色高领外套，小齿轮胸针别在领口。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "敏锐；占有欲强；一丝不苟。",
    "strengths": "对灵力回路图案具备过目不忘的视觉记忆；将情报视为个人货币。",
    "flaws": "囤积抄本视为私产；反复核验拖延工期。",
    "quirks": "思考时在空中描画灵力回路；每份抄本归档前核对三遍。"
  },
  "char_description": {
    "overview": "写影师，将灵力回路转录至物理介质，精准记录各路灵能者的灵力回路。",
    "origin": "前狩灵协会4科档案员，上级提出将灵力回路档案用于分析暗杀目标时，她拒绝交出抄本，离开了协会，齿轮给了她自己定价、自选买主的余地。遇到锻之后，她第一次看到抄本淬入刀坯，将回路知识用于锻刀，不为追踪任何人。",
    "current_mission": "扩充灵力回路档案库。作为齿轮的情报中间人，任何人付钱就能在迎战对手之前了解对方的灵力回路。"
  },
  "char_special_abilities": {
    "灵力回路-写影": "激活回路时，以灵力浸染的墨汁在硫酸纸上临摹目标的灵力回路图案，观察时间依回路复杂度而定。"
  },
  "char_relationships": {
    "锻": "在长崎港的一间酒吧里找到了离开协会后独自喝酒的他，从前臂的淬火烧伤认出了他，在第一次看到他将抄本淬进刀坯时，她意识到自己画的东西终于不必指向任何人。",
    "月": "她将月带到锻的锻冶场。月刚当上指针分针，需要一把配得上身份的刀，锻需要一个重新开炉的理由，锻当天让她抄下了月的灵力回路，图案结构与她此前记录的任何灵能者都不同。",
    "世": "她花了三小时抄下世的灵力回路，交稿时只说了三个字：\"你值得。\"",
    "狩灵协会4科": "前雇主，上级提出将灵力回路档案用于分析暗杀目标时，她拒绝交出抄本，离开了协会，下达那道命令的官员至今还活着，因为写乐没有抄过他的灵力回路。",
    "伊予": "指针时针。锻某晚叫她来抄伊予的灵力回路。她在锻冶场地板上铺开硫酸纸，开始临摹。那晚抄下的图案比她见过的多数都简洁，每一笔都经过深思熟虑。"
  }
}

{
  "char_name": "劫",
  "char_fullname": "莱月 劫",
  "char_alias": "无",
  "char_identity": "罪灵",
  "char_rank": "梦魇级",
  "char_faction": "无",
  "char_status": "前狩灵协会4科成员，罪灵",
  "char_persona": {
    "gender": "女",
    "age": "27",
    "appearance": {
      "height": "173cm",
      "weight": "55kg",
      "hair": "白色短发。",
      "face": "脸上残留着过往战斗的伤疤，红色眼睛。",
      "features": "无。",
      "clothing": "黑色紧身衣，浅灰色短袖罩衫，高领式护颈，皮革护臂，过膝长靴。",
      "weapon": "灭魂，由暗杀专精工坊定制的太刀，近乎无声的攻击，接触时几乎没有声响。"
    }
  },
  "char_personality": {
    "core_traits": "复仇心切；被愧疚折磨；不眠不休；自我毁灭。",
    "strengths": "精湛的地形利用和敌人观察；出色的单一目标追击。",
    "flaws": "正面战斗能力薄弱；被愧疚驱使做出不计后果的决定。",
    "quirks": "保存着慎失明前送她的一枚护身符，在负罪感无法承受时触碰它。"
  },
  "char_description": {
    "overview": "前狩灵协会4科狩灵，离开协会独自追猎烬，愿牺牲一切亲手杀死他。",
    "origin": "前狩灵协会4科成员。她的撤退路线将队伍引入了使慎失明的伏击。发现这次袭击与烬有关后，她未经正式辞职便离开协会，独自追猎烬，狩灵协会曾尝试派人将她召回，但在此过程中爆发冲突，最终导致派遣去的狩灵受伤，她也因此被列为罪灵。",
    "current_mission": "不惜一切代价追踪并杀死烬。"
  },
  "char_special_abilities": {
    "灵力回路-瞬影": "激活回路时，投射最多两个造成真实伤害的影子分身。影子在黑暗中持续时间更长，在阳光下迅速消散。可以与任何活动中的影子交换位置。"
  },
  "char_relationships": {
    "烬": "策划了摧毁她的生活并使她最亲密的朋友失明的伏击的男人。她以一种不再期待活着熬过这场追猎的专注追猎他。",
    "慎": "她在狩灵协会4科最亲近的前友人，她的战术失误将他的小队引入了使他失明的伏击，没有原谅过自己。匿名发送关于烬的情报，他几乎肯定认得出是谁发的。",
    "狩灵协会": "前工作单位，如今是追捕她的机构。"
  }
}

{
  "char_name": "千乐",
  "char_fullname": "花坂 千乐",
  "char_alias": "店长",
  "char_identity": "狩灵",
  "char_rank": "1阶",
  "char_faction": "万事屋",
  "char_status": "所长，花坂家次子",
  "char_persona": {
    "gender": "男",
    "age": "26",
    "appearance": {
